// Clean order: turns the AI's raw extraction into a validated order matched to a catalog SKU.
// Input: the row returned by "Log Request". Output: a clean order with valid / problem fields.

// Product dictionary. Keep it in sync with the products table (sku, bottle_ml).
const CATALOG = [
  { sku: 'AGU-CUM-700',  label: 'Cumbé Premium Aguardiente 70 cl', keywords: ['cumbe'], ml: 700 },
  { sku: 'AGU-CUM-1000', label: 'Cumbé Premium Aguardiente 1 L',   keywords: ['cumbe'], ml: 1000 },
];
const RANGE = CATALOG.map((p) => p.label).join(', ');

// Questions sent to the client, per language (fallback: English).
// Thanks to the conversation memory (Step 12), a short answer is enough.
const TEXTS = {
  en: {
    units: { case: 'cases', bottle: 'bottles' },
    or: 'or',
    unknown: (product) => `Sorry, we don't carry "${product}". Our current range: ${RANGE}.`,
    missing: () => `Which product would you like to order? Our current range: ${RANGE}.`,
    ambiguous: (options) => `Which one would you like: ${options}? Just reply with the size, e.g. "1 L".`,
    quantity: (units, label) => `How many ${units} of ${label} would you like? Just reply with a number, e.g. "3".`,
  },
  fr: {
    units: { case: 'caisses', bottle: 'bouteilles' },
    or: 'ou',
    unknown: (product) => `Désolé, nous ne proposons pas « ${product} ». Notre gamme actuelle : ${RANGE}.`,
    missing: () => `Quel produit souhaitez-vous commander ? Notre gamme actuelle : ${RANGE}.`,
    ambiguous: (options) => `Lequel souhaitez-vous : ${options} ? Répondez simplement avec le format, par exemple « 1 L ».`,
    quantity: (units, label) => `Combien de ${units} de ${label} souhaitez-vous ? Répondez simplement avec un nombre, par exemple « 3 ».`,
  },
  es: {
    units: { case: 'cajas', bottle: 'botellas' },
    or: 'o',
    unknown: (product) => `Lo sentimos, no tenemos «${product}». Nuestra gama actual: ${RANGE}.`,
    missing: () => `¿Qué producto desea pedir? Nuestra gama actual: ${RANGE}.`,
    ambiguous: (options) => `¿Cuál desea: ${options}? Responda simplemente con el formato, por ejemplo «1 L».`,
    quantity: (units, label) => `¿Cuántas ${units} de ${label} desea? Responda simplemente con un número, por ejemplo «3».`,
  },
};

// "Cumbé 1,5L" -> "cumbe 1.5l": lowercase, no accents, dot decimals
const normalize = (text) =>
  String(text ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/(\d),(\d)/g, '$1.$2')
    .trim();

// Bottle size in ml from "1L", "1 litre", "70cl", "700 ml", "0.7 l"; null if none
function parseSizeMl(text) {
  const m = text.match(/(\d+(?:\.\d+)?)\s*(ml|cl|l|litre|liter|litro)s?\b/);
  if (!m) return null;
  const factor = m[2] === 'ml' ? 1 : m[2] === 'cl' ? 10 : 1000;
  return Math.round(parseFloat(m[1]) * factor);
}

// Catalog entries whose keywords all appear in the text
const findProducts = (text) =>
  CATALOG.filter((p) => p.keywords.every((k) => text.includes(k)));

const row = $json;
const t = TEXTS[row.language] || TEXTS.en;
const productText = normalize(row.product);
const messageText = normalize(row.message);

// 1. Which product? Try the AI's product field first, then the full message
let candidates = findProducts(productText);
if (candidates.length === 0) candidates = findProducts(messageText);

// 2. Which size? Keep only the matching bottle size when the client gave one
const size = parseSizeMl(productText) ?? parseSizeMl(messageText);
const sized = candidates.filter((p) => p.ml === size);
if (sized.length > 0) candidates = sized;

// 3. Quantity and unit (Postgres returns NUMERIC as text, e.g. "3")
const quantity = Number(row.quantity);
const unit = row.unit === 'bottle' ? 'bottle' : 'case'; // B2B default: cases

// 4. Anything we must ask the client before checking stock?
let problem = null;
let problemMessage = null;
if (candidates.length === 0) {
  problem = 'unknown_product';
  problemMessage = row.product ? t.unknown(row.product) : t.missing();
} else if (candidates.length > 1) {
  problem = 'ambiguous_product';
  problemMessage = t.ambiguous(candidates.map((p) => p.label).join(` ${t.or} `));
} else if (!Number.isInteger(quantity) || quantity <= 0) {
  problem = 'invalid_quantity';
  problemMessage = t.quantity(t.units[unit], candidates[0].label);
}

const product = candidates.length === 1 ? candidates[0] : null;

return {
  json: {
    request_id: row.id,
    chat_id: row.chat_id,
    client_name: row.client_name,
    language: row.language,
    sku: product ? product.sku : null,
    product_label: product ? product.label : null,
    quantity: Number.isFinite(quantity) ? quantity : null,
    unit,
    valid: problem === null,
    problem,
    problem_message: problemMessage,
  },
};

assignments.value:
={{ (() => {
  const d = $('Receipt data').item.json;
  const isCase = d.unit === 'case';
  const money = (n, locale) => Number(n).toLocaleString(locale, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const texts = {
    fr: `🧾 Commande n°${d.order_no} confirmée ✅

📦 ${d.product}
🔢 ${d.quantity} ${isCase ? 'caisse(s)' : 'bouteille(s)'} (${d.bottles} bouteilles)
💶 Prix unitaire : ${money(d.unit_price, 'fr-FR')} € HT
💰 Total : ${money(d.total, 'fr-FR')} € HT

Notre équipe vous contacte rapidement pour organiser la livraison. Merci !`,
    es: `🧾 Pedido n.º ${d.order_no} confirmado ✅

📦 ${d.product}
🔢 ${d.quantity} ${isCase ? 'caja(s)' : 'botella(s)'} (${d.bottles} botellas)
💶 Precio unitario: ${money(d.unit_price, 'es-ES')} € sin IVA
💰 Total: ${money(d.total, 'es-ES')} € sin IVA

Nuestro equipo le contactará pronto para organizar la entrega. ¡Gracias!`,
    en: `🧾 Order #${d.order_no} confirmed ✅

📦 ${d.product}
🔢 ${d.quantity} ${isCase ? 'case(s)' : 'bottle(s)'} (${d.bottles} bottles)
💶 Unit price: €${money(d.unit_price, 'en-GB')} excl. VAT
💰 Total: €${money(d.total, 'en-GB')} excl. VAT

Our team will contact you shortly to arrange delivery. Thank you!`,
  };
  return texts[d.language] || texts.en;
})() }}

={{ (() => {
  const label = $('Clean order').item.json.product_label;
  const bottles = $json.stock_bottles;
  const cases = Math.floor($json.stock_bottles / $('Check Stock').item.json.bottles_per_case);
  const texts = {
    fr: `😕 Désolé, il ne nous reste que ${bottles} bouteilles de ${label} (${cases} caisses complètes). Souhaitez-vous commander une quantité plus petite ?`,
    es: `😕 Lo sentimos, solo nos quedan ${bottles} botellas de ${label} (${cases} cajas completas). ¿Desea pedir una cantidad menor?`,
    en: `😕 Sorry, we only have ${bottles} bottles of ${label} left (${cases} full cases). Would you like to order a smaller quantity?`,
  };
  return texts[$('Clean order').item.json.language] || texts.en;
})() }}

